vi.mock("@notifee/react-native",()=>({default:{requestPermission:()=>notificationDevice.permission(),createChannel:async()=>"channel",createTriggerNotification:async(notification:{id:string},trigger:unknown)=>{notificationDevice.rows.set(notification.id,trigger);return notification.id;},cancelNotification:async(id:string)=>{notificationDevice.rows.delete(id);},cancelAllNotifications:async()=>{notificationDevice.rows.clear();},getTriggerNotifications:async()=>[...notificationDevice.rows].map(([id,trigger])=>({notification:{id},trigger})),getDisplayedNotifications:async()=>[]},TriggerType:{TIMESTAMP:0},RepeatFrequency:{DAILY:1}}));

