const USER="a".repeat(32),OTHER="b".repeat(32);
const nativeDelete=files.deleteAsync.getMockImplementation()!;
let session:ReturnType<typeof useSession>,root:Root|undefined,serverDays:unknown,responseStatus:number,serverUnlockDays:unknown;
