async function mount(unlockDays=45){root=await render(<SessionProvider><Probe/></SessionProvider>);await vi.waitFor(()=>expect(state()).toEqual({auth:"loggedIn",unlocked:false,days:5,known:true,loading:false,unlockDays,erasure:false}));}
beforeEach(async()=>{
 vi.useRealTimers();vi.restoreAllMocks();storage.__reset();files.__resetFiles();files.deleteAsync.mockImplementation(nativeDelete);runTestControl(setSecureStoreBackend,null);runTestControl(__resetLocalKeyLifecycleForTests);vault.lock();serverDays=5;responseStatus=200;serverUnlockDays=45;
 await api.setSession("native-bearer",USER,"alice");
 notificationDevice.rows=new Map();notificationDevice.permission=async()=>({authorizationStatus:1});const notifications=notificationDevice.rows;vi.stubGlobal("require",(name:string)=>{if(name!=="@notifee/react-native")throw new Error("unavailable native module "+name);return {default:{getTriggerNotifications:async()=>[...notifications].map(([id,trigger])=>({notification:{id},trigger})),getDisplayedNotifications:async()=>[],cancelNotification:async(id:string)=>{notifications.delete(id);},cancelAllNotifications:async()=>{notifications.clear();},createChannel:async()=>"channel",createTriggerNotification:async(notification:{id:string},trigger:unknown)=>{notifications.set(notification.id,trigger);return notification.id;},requestPermission:async()=>({authorizationStatus:1})},TriggerType:{TIMESTAMP:0},RepeatFrequency:{DAILY:1}};});
 vi.stubGlobal("fetch",vi.fn(async(url:string)=>{const path=new URL(url).pathname;let value:unknown;if(path.endsWith("/insights"))value=responseStatus===200?{active_days:serverDays}:{code:"account_deleted",detail:"untrusted account response"};else if(path.endsWith("/meta"))value={unlock_days:serverUnlockDays};else if(path.endsWith("/auth/logout"))value={};else throw new Error("unexpected native route "+path);const response=new Response(JSON.stringify(value),{status:path.endsWith("/insights")?responseStatus:200});Object.defineProperty(response,"url",{value:url});return response;}));
});
afterEach(async()=>{if(root){await act(async()=>root!.unmount());root=undefined;}vi.useRealTimers();vi.restoreAllMocks();vault.lock();await api.clearSession();vi.unstubAllGlobals();});
